style.css:
@-moz-document domain("discord.com") {
/* Fundo geral */
  body {
    background-color: #1e1e2f !important; /* Cor de fundo personalizada */
    color: #ffffff !important; /* Cor do texto */
  }

  /* Cor da barra lateral */
  .sidebar-2K8pFh {
    background-color: #29293d !important;
  }

  /* Cor do texto dos canais */
  .name-3DqH6s {
    color: #00d4ff !important; /* Azul claro */
    font-family: "Comic Sans MS", cursive !important; /* Fonte personalizada */
  }

  /* Fundo das mensagens */
  .content-3YMskv {
    background-color: #252535 !important;
    border-radius: 8px !important;
    padding: 8px !important;
    color: #f0f0f0 !important;
  }

  /* Texto das mensagens */
  .markup-2BOw-j {
    font-family: "Arial", sans-serif !important; /* Fonte personalizada */
    color: #ffffff !important;
  }

  /* Alterar a cor das mensagens de entrada */
  .message-2qnXI6:hover {
    background-color: #393951 !important;
  }

  /* Botões e ícones */
  .icon-3o6xvg {
    filter: invert(70%) !important; /* Efeito de inversão para ícones */
  }

  /* Fundo da barra superior */
  .titleBar-AC4pGV {
    background-color: #1c1c28 !important;
  }
}
